import{bV as a,aL as i,u as e,G as t}from"./chunks/framework.CzwWnRE6.js";const k=JSON.parse('{"title":"Threejs","description":"","frontmatter":{"title":"Threejs","date":"2025-02-20T14:22:25.000Z","categories":["threejs"],"permalink":"/pages/01f913"},"headers":[],"relativePath":"threejs/index.md","filePath":"threejs/index.md","lastUpdated":null}'),l={name:"threejs/index.md"};function n(r,s,h,o,p,d){return i(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="threejs" tabindex="-1">Threejs <a class="header-anchor" href="#threejs" aria-label="Permalink to &quot;Threejs&quot;">​</a></h1><p>Three.js 是一个基于 JavaScript 的 3D 图形库，它简化了在网页上创建和展示 3D 图形的过程，让开发者能够在浏览器中轻松实现各种复杂的 3D 场景和交互效果。</p><h2 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to &quot;特点&quot;">​</a></h2><ul><li>完全基于 JavaScript，无需依赖其他插件或库。</li><li>支持多种渲染器，包括 WebGL、Canvas2D 和 CSS3D。</li><li>提供丰富的 3D 对象和材质，包括几何体、光照、纹理等。</li><li>支持动画、物理引擎、粒子系统等高级功能。</li><li>社区活跃，有大量的示例和教程可供参考。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><ul><li><strong>场景（Scene）：</strong> 3D 对象容器，如同舞台，所有元素需添加到场景中渲染。</li><li><strong>相机（Camera）：</strong> 决定观察视角和范围，常用透视与正交相机。</li><li><strong>渲染器（Renderer）：</strong> 将场景和相机组合，把 3D 场景渲染成 2D 图像，常用 WebGL 渲染器。</li><li><strong>几何体（Geometry）：</strong> 定义 3D 对象形状，有内置和自定义类型。</li><li><strong>材质（Material）：</strong> 决定几何体外观，如颜色、纹理、光泽，有多种类型。</li><li><strong>网格（Mesh）：</strong> 几何体和材质的组合，是常见 3D 对象。</li></ul><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>游戏开发：</strong> 创建网页 3D 游戏。</li><li><strong>数据可视化：</strong> 以 3D 图形直观呈现复杂数据关系和趋势。</li><li><strong>VR/AR：</strong> 开发基于浏览器的虚拟和增强现实应用。</li><li><strong>建筑与室内设计：</strong> 展示设计方案，让客户提前感受空间布局。</li><li><strong>教育和培训：</strong> 创建交互式 3D 教学内容，助于理解抽象概念。</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>可以通过 npm 或 yarn 安装 Three.js：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> three</span></span></code></pre></div><p>或</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> three</span></span></code></pre></div><p>导入</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> THREE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;three&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div>',15)])])}const c=a(l,[["render",n]]);export{k as __pageData,c as default};
